import{_ as e,o as n,c as d,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"10 — Roles & Permissions Matrix (tổng hợp)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/10-roles-permissions-matrix.md","filePath":"ba/10-roles-permissions-matrix.md"}'),r={name:"ba/10-roles-permissions-matrix.md"};function o(c,t,h,i,g,l){return n(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="_10-—-roles-permissions-matrix-tong-hop" tabindex="-1">10 — Roles &amp; Permissions Matrix (tổng hợp) <a class="header-anchor" href="#_10-—-roles-permissions-matrix-tong-hop" aria-label="Permalink to &quot;10 — Roles &amp; Permissions Matrix (tổng hợp)&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><h2 id="_1-bang-role-he-thong-v2" tabindex="-1">1. Bảng role hệ thống V2 <a class="header-anchor" href="#_1-bang-role-he-thong-v2" aria-label="Permalink to &quot;1. Bảng role hệ thống V2&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cấp</th><th>Role</th><th>Phạm vi</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Chưa đăng nhập</td><td><code>GUEST</code></td><td>Toàn hệ thống</td><td>Landing page, Sign Up, Sign In only</td></tr><tr><td>Đã đăng nhập, chưa vào Agency</td><td><code>USER</code></td><td>Cá nhân</td><td>Có Profile riêng, tạo được Agency mới, quản lý Subscription cá nhân</td></tr><tr><td>Agency</td><td><code>OWNER</code></td><td>1 Agency cụ thể</td><td>Duy nhất 1 Owner/Agency, gắn 1-1 với user tạo ra Agency</td></tr><tr><td>Agency</td><td><em>(Member không role)</em></td><td>1 Agency cụ thể</td><td>Invite vào Agency nhưng CHƯA có quyền quản lý gì — chỉ có quyền khi được add vào 1 Workspace cụ thể</td></tr><tr><td>Workspace</td><td><code>OWNER</code></td><td>1 Workspace cụ thể</td><td>Owner của Agency có thể tự nhận vai trò này ở 1/nhiều Workspace</td></tr><tr><td>Workspace</td><td><code>MANAGER</code></td><td>1 Workspace cụ thể</td><td>Toàn quyền quản lý Workspace đó — KHÔNG áp dụng sang Workspace khác cùng Agency</td></tr><tr><td>Workspace</td><td><code>MEMBER</code> (bao gồm CREATOR)</td><td>1 Workspace cụ thể</td><td>Creator là 1 dạng Member có quyền tạo content</td></tr><tr><td>Workspace (ngoài)</td><td><code>CLIENT</code></td><td>1 hoặc nhiều Workspace</td><td>Actor ngoài Agency, Profile riêng dùng lại xuyên Agency/Workspace</td></tr><tr><td>Hệ thống</td><td><code>ADMIN</code></td><td>Toàn hệ thống</td><td>Tách biệt hoàn toàn, không thuộc Agency nào</td></tr></tbody></table><p><strong>Quy tắc cốt lõi (nhắc lại từ <a href="./01-organization-structure.html">01-organization-structure.md</a>):</strong> role Workspace (OWNER/MANAGER/MEMBER) <strong>gán độc lập theo từng Workspace</strong> — 1 user có thể có role khác nhau ở các Workspace khác nhau trong cùng 1 Agency.</p><h2 id="_1-1-ma-tran-quyen-2-tang-v2-—-agency-level-vs-workspace-level" tabindex="-1">1.1 Ma trận quyền 2 tầng (V2) — Agency-level vs Workspace-level <a class="header-anchor" href="#_1-1-ma-tran-quyen-2-tang-v2-—-agency-level-vs-workspace-level" aria-label="Permalink to &quot;1.1 Ma trận quyền 2 tầng (V2) — Agency-level vs Workspace-level&quot;">​</a></h2><p>&gt; Cập nhật theo DA-E14-06, phản ánh model RBAC 2 tầng: <strong>Agency-level</strong> (chỉ <code>owner_id</code>, kiểm tra riêng biệt với <code>@RequireRole</code>) nằm trên <strong>Workspace-level</strong> (<code>MemberRole</code> theo từng Workspace, cơ chế <code>@RequireRole</code> hiện có).</p><h3 id="tang-1-—-agency-level-chi-agency-owner-khong-phu-thuoc-memberrole-o-workspace-nao" tabindex="-1">Tầng 1 — Agency-level (chỉ Agency Owner, không phụ thuộc MemberRole ở Workspace nào) <a class="header-anchor" href="#tang-1-—-agency-level-chi-agency-owner-khong-phu-thuoc-memberrole-o-workspace-nao" aria-label="Permalink to &quot;Tầng 1 — Agency-level (chỉ Agency Owner, không phụ thuộc MemberRole ở Workspace nào)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>FR</th><th>Hành động</th><th>Role bắt buộc</th><th>Ghi chú</th></tr></thead><tbody><tr><td>3.4.1</td><td>List Agency (của mình)</td><td>OWNER</td><td></td></tr><tr><td>3.4.2</td><td>View Agency Dashboard</td><td>OWNER</td><td></td></tr><tr><td>3.4.3</td><td>Create Agency</td><td>USER (bất kỳ user đã đăng nhập)</td><td>Tạo xong tự thành OWNER của Agency đó</td></tr><tr><td>3.4.4</td><td>View Agency Profile</td><td>OWNER</td><td></td></tr><tr><td>3.4.5</td><td>Update Agency Profile</td><td>OWNER</td><td></td></tr><tr><td>3.4.6</td><td>Remove Agency</td><td>OWNER</td><td>Soft delete, khôi phục 30 ngày</td></tr><tr><td>3.4.7</td><td>Invite Agency Member</td><td>OWNER</td><td></td></tr><tr><td>3.4.8</td><td>View Agency Invitation Status</td><td>OWNER / USER (invited)</td><td>2 phía đều xem được</td></tr><tr><td>3.4.9</td><td>Remove Agency Member</td><td>OWNER</td><td></td></tr><tr><td>3.4.10</td><td>List Workspace (toàn bộ của Agency)</td><td>OWNER</td><td>Member chỉ thấy Workspace mình có mặt — xem Tầng 2</td></tr></tbody></table><h3 id="tang-2-—-workspace-level-theo-memberrole-cua-tung-workspace-cu-the" tabindex="-1">Tầng 2 — Workspace-level (theo <code>MemberRole</code> của từng Workspace cụ thể) <a class="header-anchor" href="#tang-2-—-workspace-level-theo-memberrole-cua-tung-workspace-cu-the" aria-label="Permalink to &quot;Tầng 2 — Workspace-level (theo `MemberRole` của từng Workspace cụ thể)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>FR</th><th>Hành động</th><th>Role bắt buộc</th><th>Ghi chú</th></tr></thead><tbody><tr><td>3.4.10</td><td>List Workspace (của riêng mình)</td><td>MEMBER</td><td>Chỉ Workspace mình có mặt</td></tr><tr><td>3.4.11</td><td>View Workspace Dashboard</td><td>OWNER / MANAGER / MEMBER</td><td>Owner Agency luôn xem được mọi Workspace (kế thừa Tầng 1)</td></tr><tr><td>3.4.12</td><td>Create Workspace</td><td>OWNER (Agency)</td><td>Bắt buộc gán đúng 1 Manager lúc tạo</td></tr><tr><td>3.4.13</td><td>View Workspace Profile</td><td>MANAGER</td><td></td></tr><tr><td>3.4.14</td><td>Update Workspace Profile</td><td>MANAGER</td><td></td></tr><tr><td>3.4.15</td><td>Delete Workspace</td><td>OWNER (Agency)</td><td>Soft delete, khôi phục 30 ngày</td></tr><tr><td>3.4.16</td><td>Leave Workspace</td><td>MEMBER</td><td></td></tr><tr><td>3.4.17</td><td>Save Workspace Template</td><td>OWNER (Agency)</td><td></td></tr><tr><td>3.4.18</td><td>View Workspace Members</td><td>MEMBER</td><td></td></tr><tr><td>3.4.19</td><td>Add Workspace Member</td><td>MANAGER</td><td>Member phải đã thuộc Agency trước</td></tr><tr><td>3.4.20</td><td>Update Workspace Member Role</td><td>MANAGER</td><td></td></tr><tr><td>3.4.21</td><td>Remove Workspace Member</td><td>MANAGER</td><td>Không xóa khỏi Agency</td></tr></tbody></table><h3 id="mau-email-theo-scope-fr-3-6-28-32-addendum-b-—-cap-nhat-2026-10-29" tabindex="-1">Mẫu email theo scope (FR 3.6.28-32, Addendum B — cập nhật 2026-10-29) <a class="header-anchor" href="#mau-email-theo-scope-fr-3-6-28-32-addendum-b-—-cap-nhat-2026-10-29" aria-label="Permalink to &quot;Mẫu email theo scope (FR 3.6.28-32, Addendum B — cập nhật 2026-10-29)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Tạo/sửa</th><th>Gửi</th><th>Ghi chú</th></tr></thead><tbody><tr><td><code>WORKSPACE_MANAGER</code>, <code>CAMPAIGN_BROADCAST</code></td><td>Workspace OWNER / MANAGER / CREATOR</td><td>Workspace OWNER / MANAGER / CREATOR</td><td>Người nhận phải nêu tường minh hoặc backend suy ra theo scope</td></tr><tr><td><code>AGENCY_INTERNAL</code>, <code>AGENCY_CLIENT</code></td><td>Agency OWNER, Manager của Workspace thuộc Agency</td><td>Agency OWNER (toàn Agency) hoặc Manager (chỉ trong Workspace của mình), qua Workspace thuộc Agency đó</td><td>Cập nhật 2026-10-29 (B20); Creator và người ngoài Agency nhận <code>TEMPLATE_NOT_FOUND</code></td></tr><tr><td><code>ADMIN_SYSTEM_BROADCAST</code></td><td>ADMIN</td><td>ADMIN (endpoint <code>/api/v1/admin/...</code>, không cần Workspace)</td><td>Member Workspace chỉ dùng được mẫu hệ thống với danh sách người nhận tường minh và cap 200/lần</td></tr><tr><td><code>TRANSACTIONAL_AUTO</code></td><td>ADMIN</td><td>Hệ thống tự gửi (không ai bấm gửi tay)</td><td>Ẩn khỏi Workspace</td></tr></tbody></table><p>Quyền theo từng trang web/mobile: xem <a href="./../feature/mobile-nav-role-parity/spec.html">mobile-nav-role-parity</a>.</p><p><strong>Nguyên tắc kỹ thuật:</strong> Tầng 1 dùng check riêng (<code>agency.getOwnerId().equals(currentUserId)</code> hoặc tương đương <code>@RequireAgencyOwner</code>), KHÔNG dùng chung cơ chế <code>@RequireRole(MemberRole...)</code> của Tầng 2 — 2 cơ chế độc lập, một Agency Owner không tự động có <code>MemberRole</code> ở mọi Workspace con trừ khi được gán riêng (trừ hành động list/view đã liệt kê ở Tầng 1 do kế thừa quyền sở hữu).</p><p><strong>Phạm vi mở rộng (E16, E50, E51):</strong> endpoint các nhóm Agency &amp; Client (E16), Media Package/Campaign (E50), Task workflow (E51) áp dụng theo cùng nguyên tắc 2 tầng ở trên — chi tiết role từng FR xem file <a href="./04-media-package-campaign.html">04</a> và <a href="./05-content-task-workflow.html">05</a>; các FR đó đã dùng đúng model Workspace-level (<code>MemberRole</code>) hiện có, không cần bảng riêng.</p><h2 id="_2-ma-tran-quyen-theo-tung-nhom-fr" tabindex="-1">2. Ma trận quyền theo từng nhóm FR <a class="header-anchor" href="#_2-ma-tran-quyen-theo-tung-nhom-fr" aria-label="Permalink to &quot;2. Ma trận quyền theo từng nhóm FR&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nhóm FR</th><th>File chi tiết</th><th>Role tham gia chính</th></tr></thead><tbody><tr><td>3.2 Authentication</td><td><a href="./02-authentication-profile.html">02</a></td><td>GUEST, USER</td></tr><tr><td>3.3 Profile</td><td><a href="./02-authentication-profile.html">02</a></td><td>USER</td></tr><tr><td>3.4 Agency &amp; Workspace</td><td><a href="./03-agency-workspace-management.html">03</a></td><td>OWNER, MEMBER, MANAGER</td></tr><tr><td>3.5 Media Package &amp; Contract</td><td><a href="./04-media-package-campaign.html">04</a></td><td>OWNER, MANAGER, CLIENT</td></tr><tr><td>3.6 Content &amp; Workflow</td><td><a href="./05-content-task-workflow.html">05</a></td><td>CREATOR, MANAGER, CLIENT</td></tr><tr><td>3.7 AI Features</td><td><a href="./06-ai-features.html">06</a></td><td>CREATOR, ADMIN</td></tr><tr><td>3.8 Publishing &amp; Social</td><td><a href="./07-publishing-social-collaborator.html">07</a></td><td>CLIENT, MEMBER</td></tr><tr><td>3.9 Subscription</td><td><a href="./08-subscription-billing.html">08</a></td><td>USER, OWNER, CREATOR</td></tr><tr><td>3.10 Admin Management</td><td><a href="./09-admin-management.html">09</a></td><td>ADMIN</td></tr></tbody></table><h2 id="_3-đac-biet-fr-co-role-hon-hop-can-luu-y-khi-thiet-ke-rbac" tabindex="-1">3. Đặc biệt: FR có role hỗn hợp cần lưu ý khi thiết kế RBAC <a class="header-anchor" href="#_3-đac-biet-fr-co-role-hon-hop-can-luu-y-khi-thiet-ke-rbac" aria-label="Permalink to &quot;3. Đặc biệt: FR có role hỗn hợp cần lưu ý khi thiết kế RBAC&quot;">​</a></h2><p>Các trường hợp role list trong CSV có nhiều actor nhưng <strong>hành động thực tế KHÔNG đồng đều</strong> giữa các actor đó — quan trọng để tránh thiết kế permission sai:</p><table tabindex="0"><thead><tr><th>FR</th><th>Role list (CSV)</th><th>Ai THỰC SỰ thao tác</th><th>Ai chỉ có quyền XEM/DUYỆT</th></tr></thead><tbody><tr><td>3.5.7 Create Content Request</td><td>OWNER/MANAGER/CLIENT</td><td>CLIENT (tạo)</td><td>OWNER/MANAGER (xem, duyệt sau)</td></tr><tr><td>3.5.3 Request Media Package</td><td>OWNER/MANAGER/CLIENT</td><td>CLIENT (đề xuất thay đổi)</td><td>OWNER/MANAGER (phản hồi)</td></tr><tr><td>3.5.8 Track Request Status</td><td>ghi MANAGER</td><td>MANAGER (set trạng thái)</td><td>CLIENT không set được, chỉ xem</td></tr></tbody></table><h2 id="_4-chuoi-approval-—-vai-tro-theo-thu-tu-tong-hop-tu-file-05" tabindex="-1">4. Chuỗi Approval — vai trò theo thứ tự (tổng hợp từ file 05) <a class="header-anchor" href="#_4-chuoi-approval-—-vai-tro-theo-thu-tu-tong-hop-tu-file-05" aria-label="Permalink to &quot;4. Chuỗi Approval — vai trò theo thứ tự (tổng hợp từ file 05)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Media Package:   Client đề xuất → Owner/Manager phản hồi → CẢ 2 approve</span></span>\n<span class="line"><span>Media Campaign:  Agency tạo → CẢ 2 (Owner/Manager + Client) approve</span></span>\n<span class="line"><span>Task:            Creator làm → [QC Creator khác, tùy chọn] → Manager duyệt → Client duyệt (nếu cần)</span></span></code></pre></div><p>Mỗi tầng approval đều yêu cầu <strong>đồng thuận 2 phía</strong> (Agency internal + Client) trước khi tiến sang bước kế — điểm chung xuyên suốt toàn bộ nghiệp vụ BrandHub V2, khác với hệ thống cũ (chỉ cần nội bộ Agency duyệt qua các cấp, Client duyệt cuối 1 lần).</p><h2 id="_5-cau-hoi-rbac-đa-chot-confirmed-2026-09-17" tabindex="-1">5. Câu hỏi RBAC đã chốt [CONFIRMED 2026-09-17] <a class="header-anchor" href="#_5-cau-hoi-rbac-đa-chot-confirmed-2026-09-17" aria-label="Permalink to &quot;5. Câu hỏi RBAC đã chốt [CONFIRMED 2026-09-17]&quot;">​</a></h2><ol><li><strong>[09-admin-management.md]</strong> Admin KHÔNG xóa được Admin khác. Không giới hạn cứng số lượng Admin.</li><li><strong>[02-authentication-profile.md]</strong> Field cụ thể của User Profile (FR 3.3.1) — đã chốt đầy đủ 10 field (fullName, avatar, email, phone, professionalTitle, bio, portfolioUrl, workingLanguage, timezone, joinedAt).</li><li><strong>[05-content-task-workflow.md]</strong> Check Copyright Infringement (FR 3.6.34) — dùng API bên thứ 3 (reverse image search).</li><li><strong>[05-content-task-workflow.md]</strong> Mail Template (FR 3.6.28–3.6.32) — tính năng chung toàn bộ USER, không giới hạn theo role Workspace.</li><li><strong>[07-publishing-social-collaborator.md]</strong> Third-party Collaborator — entity/DB schema đã chốt tại <a href="./11-data-entities-glossary.html">11-data-entities-glossary.md</a> (đóng 2026-09-15); số hiệu FR chính thức trong CSV gốc vẫn còn treo, cần Trung tự bổ sung khi cập nhật CSV.</li></ol><h2 id="_6-cau-hoi-rbac-con-mo-khac-phat-sinh-2026-09-17-can-tiep-tuc-quyet-đinh-khi-thiet-ke-ky-thuat" tabindex="-1">6. Câu hỏi RBAC còn mở khác (phát sinh 2026-09-17, cần tiếp tục quyết định khi thiết kế kỹ thuật) <a class="header-anchor" href="#_6-cau-hoi-rbac-con-mo-khac-phat-sinh-2026-09-17-can-tiep-tuc-quyet-đinh-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;6. Câu hỏi RBAC còn mở khác (phát sinh 2026-09-17, cần tiếp tục quyết định khi thiết kế kỹ thuật)&quot;">​</a></h2><ol><li><strong>[05-content-task-workflow.md]</strong> Content Writing (FR 3.6.10) — đã mở role cho cả MANAGER sửa trực tiếp nội dung (không chỉ CREATOR), cần thiết kế UI/API rõ cơ chế khóa/lock khi 2 người cùng sửa đồng thời để tránh mất dữ liệu (concurrent edit).</li><li><strong>[12-state-machines.md]</strong> Approval Sequence reject-loop giờ luôn quay lại <code>[QC_REVIEW]</code> khi có giao QC — cần xác nhận thêm: nếu Task <strong>không giao QC</strong> (QC optional = không chọn), reject ở Manager/Client vẫn chỉ quay về <code>[ASSIGNED]</code> như cũ, không phát sinh thêm bước nào.</li><li><strong>[04-media-package-campaign.md], [12-state-machines.md]</strong> Campaign Addendum — mới thêm entity, chưa xác định rõ role nào được TẠO Addendum (đề xuất mặc định giống Campaign gốc: OWNER/MANAGER/CLIENT, cần Trung xác nhận có đúng không hay chỉ nội bộ Agency mới tạo được, không cho Client tự tạo Addendum).</li></ol>',28)])])}const m=e(r,[["render",o]]);export{p as __pageData,m as default};
